#!/usr/bin/env bash
# SPDX-License-Identifier: MIT
#
# Static checks for the Argo CD app of apps rendered by argocd-bootstrap.
#
# Usage:
#   argocd-bootstrap/tests/check-projects.sh [--deep] [CLUSTER...]
#
# CLUSTER is a directory name under clusters/ (default: every
# clusters/*/cluster.yaml). Each cluster is rendered in three variants: as
# configured, with applicationSet.enabled=true, and with every toolchain
# switch enabled. The root Application rendered by bootstrap/ is checked
# together with each variant. Applications generated by list generators of
# ApplicationSets are expanded and checked like static ones.
#
# Checks: unique names; Application names are DNS labels; no Application uses
# the default project and every project is rendered; destinations are
# permitted by the project; manifest-generate-paths entries, source paths and
# value files exist. With --deep, every Helm chart of this repository that an
# Application deploys is rendered the way Argo CD renders it, and each object
# is checked against the Application's AppProject.
#
# Prints one error line per violation and exits 1 when there is any.
# Requires helm, yq (mikefarah v4) and jq. --deep downloads chart dependencies
# that are not vendored; when that fails the chart is skipped with a warning.

# shellcheck source=scripts/lib/common.sh
source "$(dirname "${BASH_SOURCE[0]}")/../../scripts/lib/common.sh"

usage() {
  awk 'NR > 3 && /^#/ { sub(/^# ?/, ""); print; next } NR > 3 { exit }' "${BASH_SOURCE[0]}"
}

DEEP=0
clusters=()
while (($# > 0)); do
  case "$1" in
    --deep) DEEP=1 ;;
    -h | --help)
      usage
      exit 0
      ;;
    -*) die "unknown option: $1 (see --help)" 2 ;;
    *) clusters+=("$1") ;;
  esac
  shift
done

require_cmd helm yq jq
yq --version 2>/dev/null | grep -q mikefarah || die "yq must be the Go implementation (mikefarah/yq v4)"

cd "$REPO_ROOT" || exit 1

if ((${#clusters[@]} == 0)); then
  for f in clusters/*/cluster.yaml; do
    [[ -f "$f" ]] || continue
    c="${f#clusters/}"
    clusters+=("${c%/cluster.yaml}")
  done
fi
((${#clusters[@]} > 0)) || die "no cluster definitions found under clusters/"
for c in "${clusters[@]}"; do
  [[ -f "clusters/${c}/cluster.yaml" ]] || die "cluster definition not found: clusters/${c}/cluster.yaml" 2
done

make_temp_dir WORK check-projects
mkdir -p "$WORK/render" "$WORK/mirror"
: >"$WORK/specs"
: >"$WORK/prepared"
: >"$WORK/helm-repos"
: >"$WORK/assumed"

# Helm runs with private configuration, cache and data directories, so that
# repositories added for dependency builds never touch the caller's Helm setup.
export HELM_CONFIG_HOME="$WORK/helm/config"
export HELM_CACHE_HOME="$WORK/helm/cache"
export HELM_DATA_HOME="$WORK/helm/data"
export HELM_REPOSITORY_CONFIG="$HELM_CONFIG_HOME/repositories.yaml"
export HELM_REPOSITORY_CACHE="$HELM_CACHE_HOME/repository"
export HELM_REGISTRY_CONFIG="$HELM_CONFIG_HOME/registry/config.json"

US=$'\x1f'
errors=0
warnings=0

fail() {
  log_error "$1"
  errors=$((errors + 1))
}

warn() {
  log_warn "$1"
  warnings=$((warnings + 1))
}

# error_summary FILE: the error of a helm or yq stderr capture on one line.
# Helm 4 spreads a template error over several lines; they are joined.
error_summary() {
  local text
  text="$(awk '/^Error/ { on = 1 }
    on && !/^Use --debug/ { sub(/^[[:space:]]+/, ""); if (NF) { printf "%s%s", sep, $0; sep = " " } }' "$1")"
  if [[ -z "$text" ]]; then
    text="$(grep -v -E '^[[:space:]]*$|^level=' "$1" | head -n 1 || true)"
  fi
  text="${text#Error: }"
  printf '%s' "${text:0:600}"
}

yaml_to_json() {
  yq ea -o=json -I=0 '[.] | map(select(. != null))' "$1"
}

# ---------------------------------------------------------------------------
# jq programs
# ---------------------------------------------------------------------------
JQ_LIB="$(
  cat <<'JQ'
def norm_repo: ascii_downcase | sub("/+$"; "") | sub("\\.git$"; "");
def has_tpl: type == "string" and contains("{{");
# Repository-relative path without ".", ".." and empty segments; null when it
# leaves the repository root. A leading "/" means the repository root.
def clean_path:
  split("/")
  | reduce .[] as $s ({ok: true, p: []};
      if $s == "" or $s == "." then .
      elif $s == ".." then (if (.p | length) > 0 then .p |= .[:-1] else .ok = false end)
      else .p += [$s] end)
  | if .ok then (.p | join("/")) else null end;
def join_path($base; $rel): ($base + "/" + $rel) | clean_path;
# Anchored regular expression for a glob with "*" and "?".
def glob_re:
  "^" + ([ explode[] | [.] | implode
           | if . == "*" then ".*"
             elif . == "?" then "."
             elif test("^[A-Za-z0-9_-]$") then .
             else "\\" + . end ] | join("")) + "$";
def gm1($p; $v): ($p // "") as $p | if $p == "*" then true else (($v // "") | test($p | glob_re)) end;
# Argo CD globMatch: "*" matches anything, a leading "!" negates.
def gm($p; $v):
  ($p // "") as $p
  | if ($p | startswith("!")) then (gm1($p | .[1:]; $v) | not) else gm1($p; $v) end;
def is_deny: (. // "") | startswith("!");
# Argo CD AppProject destination matching (server or name, and namespace,
# with deny entries).
def dest_permitted($dests; $server; $name; $ns):
  reduce ($dests // [])[] as $i ({any: false, deny: false};
    ((($name // "") != "") and gm($i.name; $name)) as $nm
    | ((($server // "") != "") and gm($i.server; $server)) as $sm
    | gm($i.namespace; $ns) as $nsm
    | if ($sm or $nm) and $nsm then .any = true
      elif ((($nm | not) and ($i.name | is_deny))
            or (($sm | not) and ($i.server | is_deny))
            or (($nsm | not) and ($i.namespace | is_deny))) then .deny = true
      else . end)
  | .any and (.deny | not);
# Argo CD isResourceInList: shell glob on kind and group.
def gk_in($list; $g; $k): any(($list // [])[]; gm1(.kind; $k) and gm1(.group; $g));
def show_group: if . == "" then "core" else . end;
def show_ns: if . == "" then "\"\"" else . end;
def dest_str:
  (if (.server // "") != "" then "server \(.server)" else "name \(.name // "")" end)
  + ", namespace " + ((.namespace // "") | show_ns);
JQ
)"

# Input: --slurpfile objs (one JSON array of rendered documents), --arg repo,
# --arg prefix, --arg kube. Output: tagged items {e}, {w}, {c}, {d}, {stats}.
JQ_SHALLOW="$(
  cat <<'JQ'
def app_sources: if ((.spec.sources // []) | length) > 0 then .spec.sources else [ .spec.source // empty ] end;
def is_local($nrepo): ((.repoURL // "") | has_tpl | not) and (((.repoURL // "") | norm_repo) == $nrepo);
def subst($el; $go):
  reduce ($el | to_entries[]
          | select(.key | test("^[A-Za-z_][A-Za-z0-9_]*$"))
          | select(.value | type | IN("string", "number", "boolean"))) as $e (.;
      gsub(if $go then "\\{\\{-?\\s*\\.\($e.key)\\s*-?\\}\\}" else "\\{\\{\\s*\($e.key)\\s*\\}\\}" end;
           ($e.value | tostring | tojson | .[1:-1])));
def expand_appset($prefix):
  . as $as
  | ($as.metadata.name // "") as $asn
  | ($as.spec.goTemplate == true) as $go
  | ($as.spec.template // {} | tojson) as $t
  | reduce ($as.spec.generators // [])[] as $g ({apps: [], warnings: []};
      if ($g | has("list")) and ($g | has("selector") | not) and (($g.list.elements // null) | type) == "array" then
        .apps += [ $g.list.elements[] as $el
                   | ($t | subst($el; $go) | fromjson)
                   | .apiVersion = "argoproj.io/v1alpha1" | .kind = "Application"
                   | ._origin = "ApplicationSet \($asn)" ]
      else .warnings += ["\($prefix): ApplicationSet \($asn): generator \($g | keys | join(",")) is not a list generator with inline elements; the Applications it generates are not checked"] end)
  | if ($as.spec.templatePatch // "") != "" then .warnings += ["\($prefix): ApplicationSet \($asn): templatePatch is not applied by this check"] else . end;
# Resolves a Helm value file the way Argo CD does. Input: the raw entry.
# Output: {path, guard}, {error}, or null when it cannot be checked here.
def resolve_vf($srcs; $sp; $sl; $nrepo):
  . as $vf
  | if has_tpl or test("^[A-Za-z][A-Za-z0-9+.-]*://") then null
    elif startswith("$") then
      ([ capture("^\\$(?<ref>[^/]+)/(?<rest>.+)$") ] | first) as $m
      | if $m == null then {error: "value file \($vf) is not of the form $<ref>/<path>"}
        else ([ $srcs[] | select(.ref == $m.ref) ] | first) as $rs
          | if $rs == null then {error: "value file \($vf) refers to $\($m.ref), but no source declares ref: \($m.ref)"}
            elif ($rs | is_local($nrepo) | not) then null
            else ($m.rest | clean_path) as $r
              | if $r == null then {error: "value file \($vf) leaves the repository root"} else {path: $r, guard: ""} end
            end
        end
    elif ($sl | not) then null
    elif startswith("/") then
      clean_path as $r
      | if $r == null then {error: "value file \($vf) leaves the repository root"} else {path: $r, guard: ""} end
    elif $sp == null then null
    else join_path($sp; $vf) as $r
      | if $r == null then {error: "value file \($vf) leaves the repository root"} else {path: $r, guard: $sp} end
    end;
def app_items($pmap; $nrepo; $prefix; $kube):
  . as $a
  | ($a.metadata.name // "") as $n
  | ($a.spec.project // "") as $p0
  | (if $p0 == "" then "default" else $p0 end) as $p
  | "\($prefix): Application \($n) (project \($p))" as $pre
  | $pmap[$p] as $proj
  | ($p != "default" and $proj != null) as $projok
  | ($a.spec.destination // {}) as $d
  | ($a | app_sources) as $srcs
  | ($srcs | length > 1) as $multi
  | [ $srcs[] | select(is_local($nrepo)) ] as $local
  | (
      # 1. Name.
      ( if ($n | test("^[a-z0-9]([-a-z0-9]*[a-z0-9])?$")) then empty
        else {e: "\($pre): name is not a DNS label (lowercase letters, digits and '-', starting and ending with a letter or digit)"} end ),
      ( if ($n | length) > 63 then {e: "\($pre): name has \($n | length) characters, more than 63"} else empty end ),
      # 2. Project.
      ( if $p0 == "" then {e: "\($pre): spec.project is empty, which Argo CD treats as the default project"}
        elif $p == "default" then {e: "\($pre): uses the default project"}
        elif $proj == null then {e: "\($pre): project \($p) is not rendered in this output"}
        else empty end ),
      # 3. Destination.
      ( if ($projok | not) or ([$d.server, $d.name, $d.namespace] | any(.[]; has_tpl)) then empty
        elif (($d.server // "") == "" and ($d.name // "") == "") then {e: "\($pre): destination sets neither server nor name"}
        elif dest_permitted($proj.spec.destinations; $d.server; $d.name; ($d.namespace // "")) then empty
        else {e: "\($pre): destination \($d | dest_str) is not permitted by the project destinations"} end ),
      # 4. manifest-generate-paths.
      ( (($a.metadata.annotations // {})["argocd.argoproj.io/manifest-generate-paths"] // "") as $mgp
        | ($mgp | split(";")[] | select(. != "" and (has_tpl | not))) as $e
        | if ($local | length) == 0 then empty
          elif ($e | startswith("/")) then
            ($e | clean_path) as $r
            | if $r == null then {e: "\($pre): manifest-generate-paths entry \"\($e)\" leaves the repository root"}
              else {c: {type: "any", path: $r, guard: "", msg: "\($pre): manifest-generate-paths entry \"\($e)\" does not exist in the repository"}} end
          elif $multi then {e: "\($pre): manifest-generate-paths entry \"\($e)\" is relative in a multi-source Application; Argo CD resolves it against every source path, so it must start with /"}
          elif (($srcs[0].path // "") | has_tpl) then empty
          else join_path($srcs[0].path // ""; $e) as $r
            | if $r == null then {e: "\($pre): manifest-generate-paths entry \"\($e)\" leaves the repository root"}
              else {c: {type: "any", path: $r, guard: "", msg: "\($pre): manifest-generate-paths entry \"\($e)\" is relative to the source path and resolves to \($r), which does not exist"}} end
          end ),
      # 5. Source paths and value files.
      ( $srcs[] as $s
        | ($s | is_local($nrepo)) as $sl
        | ($s.path // null) as $raw
        | (if $raw == null or ($raw | has_tpl) then null else ($raw | clean_path) end) as $sp
        | ( if $sl and $raw != null and ($raw | has_tpl | not) then
              if $sp == null then {e: "\($pre): source path \($raw) leaves the repository root"}
              else {c: {type: "dir", path: $sp, guard: "", msg: "\($pre): source path \($raw) does not exist"}} end
            elif ($sl | not) and $raw != null and (($s.repoURL // "") | has_tpl | not) then
              {w: "\($pre): source \($s.repoURL // "") is not git.repoURL; its paths and value files are not checked"}
            else empty end ),
          ( ($s.helm.ignoreMissingValueFiles == true) as $ign
            | ($s.helm.valueFiles // [])[] as $vf
            | ($vf | resolve_vf($srcs; $sp; $sl; $nrepo)) as $res
            | if $res == null then empty
              elif $res.error != null then {e: "\($pre): \($res.error)"}
              elif $ign then empty
              else {c: {type: "file", path: $res.path, guard: $res.guard, msg: "\($pre): value file \($vf) (\($res.path)) does not exist and ignoreMissingValueFiles is not set"}} end ) ),
      # 6. Targets of the deep pass: Helm sources in this repository.
      ( $srcs[] as $s
        | select($s | is_local($nrepo))
        | select(($s.path // null) != null and ($s.path | has_tpl | not))
        | ($s.path | clean_path) as $sp
        | select($sp != null)
        | ($s.helm // {}) as $h
        | ($h.releaseName // $n) as $rel
        | select([$rel, ($d.namespace // "")] | any(.[]; has_tpl) | not)
        | {d: {app: $n, project: $p, projectOk: $projok,
               server: ($d.server // ""), dname: ($d.name // ""),
               spec: {chart: $sp, release: $rel, namespace: ($d.namespace // ""),
                      kubeVersion: ($h.kubeVersion // $kube),
                      apiVersions: ($h.apiVersions // []),
                      skipCrds: ($h.skipCrds == true),
                      valueFiles: [ ($h.valueFiles // [])[] | resolve_vf($srcs; $sp; true; $nrepo) | select(. != null and .path != null) | .path ],
                      valuesObject: ($h.valuesObject // null),
                      values: (if $h.valuesObject == null and ($h.values // "") != "" then $h.values else null end),
                      parameters: [ ($h.parameters // [])[] | {name: (.name // ""), value: ((.value // "") | tostring), forceString: (.forceString == true)} ],
                      fileParameters: (($h.fileParameters // []) | length)}}} )
    );

($objs[0]) as $objs
| ($repo | norm_repo) as $nrepo
| ($objs | map(select(.kind == "AppProject"))) as $projects
| (reduce $projects[] as $pr ({}; .[$pr.metadata.name // ""] = $pr)) as $pmap
| ($objs | map(select(.kind == "ApplicationSet"))) as $appsets
| [ $appsets[] | expand_appset($prefix) ] as $exp
| [ $exp[].apps[] ] as $generated
| [ $generated[] | select(.metadata.name | has_tpl | not) ] as $genok
| (($objs | map(select(.kind == "Application"))) + $genok) as $apps
| ( [ ($projects + $appsets + $apps)[] | {k: .kind, n: (.metadata.name // "")} ]
    | group_by([.k, .n])[]
    | select(length > 1)
    | {e: "\($prefix): \(.[0].k) \(.[0].n): name is used by \(length) objects in this render"} ),
  ( $exp[].warnings[] | {w: .} ),
  ( $generated[] | select(.metadata.name | has_tpl)
    | {w: "\($prefix): \(._origin): generated Application name \(.metadata.name) keeps a template expression; not checked"} ),
  ( $apps[] | app_items($pmap; $nrepo; $prefix; $kube) ),
  {stats: {projects: ($projects | length), appsets: ($appsets | length), apps: ($apps | length), generated: ($genok | length)}}
JQ
)"

# Input: one deep target. Output: NUL-terminated helm arguments; "A" is a
# literal argument, "F" a repository-relative value file, "O" the values file
# written from valuesObject or values.
JQ_HELM_ARGS="$(
  cat <<'JQ'
# Argo CD escapes unescaped commas in --set values, except for {a,b} lists.
def esc_set: if test("^\\{.*\\}$") then . else gsub("(?<!\\\\),"; "\\,") end;
.spec as $s
| ( (if $s.namespace != "" then "A--namespace", "A\($s.namespace)" else empty end),
    "A--kube-version", "A\($s.kubeVersion)",
    ($s.apiVersions[] | "A--api-versions", "A\(.)"),
    (if $s.skipCrds then empty else "A--include-crds" end),
    ($s.valueFiles[] | "F\(.)"),
    (if $s.valuesObject != null or $s.values != null then "O" else empty end),
    ($s.parameters[] | (if .forceString then "A--set-string" else "A--set" end), "A\(.name)=\(.value | esc_set)") )
| . + "\u0000"
JQ
)"

# Input: rendered documents. Output: one compact entry per object.
JQ_REDUCE="$(
  cat <<'JQ'
def flat: if ((.kind // "") | endswith("List")) and ((.items // null) | type) == "array" then .items[] | flat else . end;
[ .[] | flat
  | select(type == "object" and ((.kind // "") | type) == "string" and (.kind // "") != "")
  | {g: ((.apiVersion // "") | if contains("/") then split("/")[0] else "" end),
     k: .kind,
     n: (.metadata.name // ""),
     ns: (.metadata.namespace // ""),
     crd: (if .kind == "CustomResourceDefinition" and ((.apiVersion // "") | startswith("apiextensions.k8s.io/"))
           then {g: (.spec.group // ""), k: (.spec.names.kind // ""), scope: (.spec.scope // "")} else null end)} ]
JQ
)"

# Input (slurped): {t, status, objs} per deep target of one variant;
# --slurpfile root (the variant's render), --arg prefix. Output: tagged items.
JQ_DEEP="$(
  cat <<'JQ'
# Cluster-scoped kinds of Kubernetes itself, as [group, kind].
def builtin_cluster: [
  ["", "Namespace"], ["", "Node"], ["", "PersistentVolume"], ["", "ComponentStatus"],
  ["rbac.authorization.k8s.io", "ClusterRole"], ["rbac.authorization.k8s.io", "ClusterRoleBinding"],
  ["apiextensions.k8s.io", "CustomResourceDefinition"],
  ["storage.k8s.io", "StorageClass"], ["storage.k8s.io", "CSIDriver"], ["storage.k8s.io", "CSINode"],
  ["storage.k8s.io", "VolumeAttachment"], ["storage.k8s.io", "VolumeAttributesClass"],
  ["scheduling.k8s.io", "PriorityClass"], ["node.k8s.io", "RuntimeClass"],
  ["networking.k8s.io", "IngressClass"], ["networking.k8s.io", "ServiceCIDR"], ["networking.k8s.io", "IPAddress"],
  ["admissionregistration.k8s.io", "MutatingWebhookConfiguration"],
  ["admissionregistration.k8s.io", "ValidatingWebhookConfiguration"],
  ["admissionregistration.k8s.io", "ValidatingAdmissionPolicy"],
  ["admissionregistration.k8s.io", "ValidatingAdmissionPolicyBinding"],
  ["admissionregistration.k8s.io", "MutatingAdmissionPolicy"],
  ["admissionregistration.k8s.io", "MutatingAdmissionPolicyBinding"],
  ["apiregistration.k8s.io", "APIService"],
  ["certificates.k8s.io", "CertificateSigningRequest"], ["certificates.k8s.io", "ClusterTrustBundle"],
  ["flowcontrol.apiserver.k8s.io", "FlowSchema"], ["flowcontrol.apiserver.k8s.io", "PriorityLevelConfiguration"],
  ["resource.k8s.io", "DeviceClass"], ["resource.k8s.io", "ResourceSlice"], ["resource.k8s.io", "DeviceTaintRule"],
  ["storagemigration.k8s.io", "StorageVersionMigration"], ["internal.apiserver.k8s.io", "StorageVersion"]
];
# Well-known cluster-scoped kinds of add-ons, used when no CRD for the kind
# is rendered in the same deep pass.
def thirdparty_cluster: [
  ["gateway.networking.k8s.io", "GatewayClass"], ["cert-manager.io", "ClusterIssuer"],
  ["external-secrets.io", "ClusterSecretStore"], ["external-secrets.io", "ClusterExternalSecret"],
  ["kyverno.io", "ClusterPolicy"], ["kyverno.io", "ClusterCleanupPolicy"],
  ["policies.kyverno.io", "ValidatingPolicy"], ["policies.kyverno.io", "ImageValidatingPolicy"],
  ["policies.kyverno.io", "MutatingPolicy"], ["policies.kyverno.io", "GeneratingPolicy"],
  ["policies.kyverno.io", "DeletingPolicy"], ["wgpolicyk8s.io", "ClusterPolicyReport"],
  ["argoproj.io", "ClusterAnalysisTemplate"], ["postgresql.cnpg.io", "ClusterImageCatalog"]
];
# Well-known namespaced kinds of add-ons. They are classified as namespaced
# in any case; listing them only avoids the warning for unknown kinds.
def thirdparty_namespaced: [
  ["argoproj.io", "Application"], ["argoproj.io", "ApplicationSet"], ["argoproj.io", "AppProject"],
  ["bitnami.com", "SealedSecret"], ["cert-manager.io", "Certificate"], ["cert-manager.io", "Issuer"],
  ["external-secrets.io", "ExternalSecret"], ["external-secrets.io", "SecretStore"],
  ["gateway.networking.k8s.io", "Gateway"], ["gateway.networking.k8s.io", "HTTPRoute"],
  ["gateway.networking.k8s.io", "GRPCRoute"], ["gateway.networking.k8s.io", "ReferenceGrant"],
  ["kyverno.io", "Policy"], ["kyverno.io", "CleanupPolicy"], ["kyverno.io", "PolicyException"],
  ["monitoring.coreos.com", "ServiceMonitor"], ["monitoring.coreos.com", "PodMonitor"],
  ["monitoring.coreos.com", "PrometheusRule"]
];
# API groups served by Kubernetes itself: any kind in them that is not in
# builtin_cluster is namespaced.
def builtin_groups: [
  "", "apps", "batch", "autoscaling", "policy", "admissionregistration.k8s.io",
  "apiextensions.k8s.io", "apiregistration.k8s.io", "certificates.k8s.io", "coordination.k8s.io",
  "discovery.k8s.io", "events.k8s.io", "flowcontrol.apiserver.k8s.io",
  "internal.apiserver.k8s.io", "networking.k8s.io", "node.k8s.io",
  "rbac.authorization.k8s.io", "resource.k8s.io", "scheduling.k8s.io",
  "storage.k8s.io", "storagemigration.k8s.io"
];
def scope_of($crds):
  [.g, .k] as $gk
  | if ($gk | IN(builtin_cluster[])) then "Cluster"
    else ([ $crds[] | select(.g == $gk[0] and .k == $gk[1]) | .scope ] | first) as $c
      | if $c == "Cluster" or $c == "Namespaced" then $c
        elif ($gk | IN(thirdparty_cluster[])) then "Cluster"
        elif ($gk[0] | IN(builtin_groups[])) or ($gk | IN(thirdparty_namespaced[])) then "Namespaced"
        else "Assumed" end
    end;

($root[0]) as $render
| (reduce ($render[] | select(.kind == "AppProject")) as $pr ({}; .[$pr.metadata.name // ""] = $pr)) as $pmap
| . as $items
| [ $items[] | (.objs // [])[] | .crd // empty | select(.g != "" and .k != "") ] as $crds
| $items[] as $it
| $it.t as $t
| "\($prefix): Application \($t.app) (project \($t.project))" as $pre
| if ($it.status | startswith("fail:")) then {s: "failed", e: "\($pre): helm template \($t.spec.chart) failed: \($it.status | .[5:])"}
  elif ($it.status | startswith("depfail:")) then {s: "depfail", w: "\($pre): \($t.spec.chart): dependencies could not be built, chart not rendered: \($it.status | .[8:])"}
  elif $it.status == "missing" or $it.status == "notchart" then {s: $it.status}
  elif ($t.projectOk | not) then {s: "unchecked"}
  else
    $pmap[$t.project].spec as $ps
    | {s: "checked"},
      ( if $t.spec.fileParameters > 0 then {w: "\($pre): helm.fileParameters are not applied in the deep render"} else empty end ),
      ( $it.objs[] as $o
        | ($o | scope_of($crds)) as $sc
        | {o: 1},
          ( if $sc == "Assumed" then {a: "\($o.g)/\($o.k)"} else empty end ),
          ( if $sc == "Cluster" then
              "\($pre): \($o.k) \($o.g | show_group) \($o.n)" as $op
              | ( if gk_in($ps.clusterResourceWhitelist; $o.g; $o.k) then empty
                  else {e: "\($op): cluster-scoped kind is not in clusterResourceWhitelist"} end ),
                ( if gk_in($ps.clusterResourceBlacklist; $o.g; $o.k)
                  then {e: "\($op): cluster-scoped kind is in clusterResourceBlacklist"} else empty end )
            else
              (if $o.ns != "" then $o.ns else $t.spec.namespace end) as $ns
              | "\($pre): \($o.k) \($o.g | show_group) \($ns | show_ns)/\($o.n)" as $op
              | ( if dest_permitted($ps.destinations; $t.server; $t.dname; $ns) then empty
                  else {e: "\($op): namespace \($ns | show_ns) is not permitted by the project destinations"} end ),
                ( if gk_in($ps.namespaceResourceBlacklist; $o.g; $o.k)
                  then {e: "\($op): kind is in namespaceResourceBlacklist"} else empty end ),
                ( if $ps.namespaceResourceWhitelist != null and (gk_in($ps.namespaceResourceWhitelist; $o.g; $o.k) | not)
                  then {e: "\($op): kind is not in namespaceResourceWhitelist"} else empty end )
            end ) )
  end
JQ
)"

# ---------------------------------------------------------------------------
# Deep pass: chart preparation and rendering
# ---------------------------------------------------------------------------
# clean_rel PATH: prints the normalised repository-relative path, or fails
# when PATH leaves the repository.
clean_rel() {
  jq -enr --arg p "$1" "${JQ_LIB}"' $p | clean_path' 2>/dev/null
}

# mirror_chart REL: copies the chart at REL and, recursively, its file://
# dependencies into the mirror at the same relative paths. Sets MIRROR_ERR.
mirror_chart() {
  local rel="$1" dep target
  [[ -d "$WORK/mirror/$rel" ]] && return 0
  mkdir -p "$(dirname "$WORK/mirror/$rel")"
  cp -R "$REPO_ROOT/$rel" "$WORK/mirror/$rel"
  while IFS= read -r dep; do
    [[ -n "$dep" ]] || continue
    if ! target="$(clean_rel "$rel/${dep#file://}")"; then
      MIRROR_ERR="dependency ${dep} of ${rel} is outside the repository"
      return 1
    fi
    if [[ ! -f "$REPO_ROOT/$target/Chart.yaml" ]]; then
      MIRROR_ERR="dependency ${dep} of ${rel} does not exist"
      return 1
    fi
    mirror_chart "$target" || return 1
  done < <(yq '.dependencies[]?.repository // "" | select(test("^file://"))' "$REPO_ROOT/$rel/Chart.yaml")
  return 0
}

# deps_present DIR: true when helm reports every dependency as present.
deps_present() {
  helm dependency list "$1" 2>/dev/null |
    awk 'NR > 1 && NF > 0 { if ($NF != "ok" && $NF != "unpacked") bad = 1 } END { exit bad }'
}

# add_dep_repos CHART_YAML: registers the HTTP(S) repositories of the
# dependencies in the private Helm configuration. Sets DEP_ERR.
add_dep_repos() {
  local url n
  while IFS= read -r url; do
    [[ -n "$url" ]] || continue
    grep -qxF -- "$url" "$WORK/helm-repos" && continue
    n="$(wc -l <"$WORK/helm-repos" | tr -d ' ')"
    if ! helm repo add "dep$((n + 1))" "$url" --force-update >/dev/null 2>"$WORK/err"; then
      DEP_ERR="helm repo add ${url}: $(error_summary "$WORK/err")"
      return 1
    fi
    printf '%s\n' "$url" >>"$WORK/helm-repos"
  done < <(yq '.dependencies[]?.repository // "" | select(test("^https?://"))' "$1")
  return 0
}

# prepare_chart REL: sets PREP_STATUS to ok, missing (no such directory),
# notchart (no Chart.yaml) or depfail:<message>.
# The result is cached per chart for the whole run.
prepare_chart() {
  local rel="$1" cached ndeps dst="$WORK/mirror/$1"
  cached="$(awk -F "$US" -v k="$rel" '$1 == k { print $2; exit }' "$WORK/prepared")"
  if [[ -n "$cached" ]]; then
    PREP_STATUS="$cached"
    return 0
  fi
  MIRROR_ERR=""
  DEP_ERR=""
  if [[ ! -d "$REPO_ROOT/$rel" ]]; then
    PREP_STATUS="missing"
  elif [[ ! -f "$REPO_ROOT/$rel/Chart.yaml" ]]; then
    PREP_STATUS="notchart"
  elif ! mirror_chart "$rel"; then
    PREP_STATUS="depfail:${MIRROR_ERR}"
  else
    ndeps="$(yq '.dependencies // [] | length' "$REPO_ROOT/$rel/Chart.yaml")"
    if [[ "$ndeps" == "0" ]] || deps_present "$dst"; then
      PREP_STATUS="ok"
    elif ! add_dep_repos "$REPO_ROOT/$rel/Chart.yaml"; then
      PREP_STATUS="depfail:${DEP_ERR}"
    elif ! helm dependency build --skip-refresh "$dst" >/dev/null 2>"$WORK/err"; then
      PREP_STATUS="depfail:helm dependency build: $(error_summary "$WORK/err")"
    else
      PREP_STATUS="ok"
    fi
  fi
  printf '%s%s%s\n' "$rel" "$US" "$PREP_STATUS" >>"$WORK/prepared"
}

# render_spec TARGET_JSON: renders the target's chart once per distinct spec
# and sets SPEC_ID; the result is $WORK/render/<id>.{json,status}.
render_spec() {
  local spec id out chart release tok
  local -a args
  spec="$(jq -c '.spec' <<<"$1")"
  id="$(grep -nFx -- "$spec" "$WORK/specs" | head -n 1 | cut -d: -f1 || true)"
  if [[ -n "$id" ]]; then
    SPEC_ID="$id"
    return 0
  fi
  printf '%s\n' "$spec" >>"$WORK/specs"
  id="$(wc -l <"$WORK/specs" | tr -d ' ')"
  SPEC_ID="$id"
  out="$WORK/render/$id"
  echo '[]' >"$out.json"

  chart="$(jq -r '.chart' <<<"$spec")"
  release="$(jq -r '.release' <<<"$spec")"
  prepare_chart "$chart"
  if [[ "$PREP_STATUS" != "ok" ]]; then
    printf '%s\n' "$PREP_STATUS" >"$out.status"
    return 0
  fi

  args=(template "$release" "$WORK/mirror/$chart")
  while IFS= read -r -d '' tok; do
    case "$tok" in
      A*) args+=("${tok#A}") ;;
      F*)
        if [[ -f "$REPO_ROOT/${tok#F}" ]]; then
          args+=(-f "$REPO_ROOT/${tok#F}")
        fi
        ;;
      O)
        jq -r 'if .valuesObject != null then .valuesObject else .values end' <<<"$spec" >"$out.values.yaml"
        args+=(-f "$out.values.yaml")
        ;;
    esac
  done < <(jq -j "$JQ_HELM_ARGS" <<<"$1")

  log_debug "render ${id}: helm ${args[*]}"
  if helm "${args[@]}" >"$out.yaml" 2>"$out.err"; then
    if yaml_to_json "$out.yaml" 2>"$out.err" | jq -c "$JQ_REDUCE" >"$out.json"; then
      echo ok >"$out.status"
      log_debug "render ${id}: $(jq -r '[.[] | "\(.k)/\(.ns)/\(.n)"] | join(" ")' "$out.json")"
    else
      echo '[]' >"$out.json"
      printf 'fail:rendered output is not valid YAML: %s\n' "$(error_summary "$out.err")" >"$out.status"
    fi
  else
    printf 'fail:%s\n' "$(error_summary "$out.err")" >"$out.status"
  fi
}

# deep_variant PREFIX ANALYSIS RENDER_JSON: renders the deep targets and
# checks their objects. Sets DEEP_SUMMARY.
deep_variant() {
  local prefix="$1" analysis="$2" render="$3" items t result line
  items="$WORK/deep-items.jsonl"
  result="$WORK/deep-result.jsonl"
  : >"$items"
  while IFS= read -r t; do
    render_spec "$t"
    jq -c --slurpfile objs "$WORK/render/${SPEC_ID}.json" --rawfile status "$WORK/render/${SPEC_ID}.status" \
      '{t: ., status: ($status | rtrimstr("\n")), objs: $objs[0]}' <<<"$t" >>"$items"
  done < <(jq -c '.d // empty' "$analysis")

  jq -c -s --slurpfile root "$render" --arg prefix "$prefix" "${JQ_LIB}${JQ_DEEP}" "$items" >"$result"

  while IFS= read -r line; do fail "$line"; done < <(jq -r '.e // empty' "$result" | sort -u)
  while IFS= read -r line; do warn "$line"; done < <(jq -r '.w // empty' "$result" | sort -u)
  jq -r '.a // empty' "$result" >>"$WORK/assumed"
  DEEP_SUMMARY="$(jq -rs '
    def n($s): map(select(.s == $s)) | length;
    "Helm sources checked: \(n("checked")) (\(map(select(.o)) | length) objects); not checked: "
    + "\(n("unchecked")) project default or not rendered, \(n("failed")) render failed, "
    + "\(n("depfail")) dependencies unavailable, \(n("missing")) path missing, \(n("notchart")) not a Helm chart"
  ' "$result")"
}

# ---------------------------------------------------------------------------
# Shallow checks per variant
# ---------------------------------------------------------------------------
# check_variant CLUSTER VARIANT [HELM_ARG...]
check_variant() {
  local cluster="$1" variant="$2"
  shift 2
  local prefix="${cluster}/${variant}" before="$errors"
  local render_yaml="$WORK/${cluster}.${variant}.yaml"
  local render_json="$WORK/${cluster}.${variant}.json"
  local objs_json="$WORK/${cluster}.${variant}.objs.json"
  local analysis="$WORK/${cluster}.${variant}.analysis.jsonl"
  local tag ctype path guard msg stats
  DEEP_SUMMARY=""

  if ! helm template root argocd-bootstrap -f "clusters/${cluster}/cluster.yaml" "$@" >"$render_yaml" 2>"$WORK/err"; then
    fail "${prefix}: helm template argocd-bootstrap failed: $(error_summary "$WORK/err")"
    return 0
  fi
  if ! yaml_to_json "$render_yaml" >"$render_json" 2>"$WORK/err"; then
    fail "${prefix}: rendered output is not valid YAML: $(error_summary "$WORK/err")"
    return 0
  fi
  jq -c -s 'add' "$render_json" "$WORK/${cluster}.bootstrap.json" >"$objs_json"

  jq -c -n --slurpfile objs "$objs_json" --arg repo "$CL_REPO" --arg prefix "$prefix" \
    --arg kube "$CL_KUBE" "${JQ_LIB}${JQ_SHALLOW}" >"$analysis"

  # Errors, warnings and path checks in render order, so that the lines of
  # one Application stay together. A path check applies only when its guard
  # directory (the source path of a relative value file) exists.
  while IFS="$US" read -r tag ctype path guard msg; do
    case "$tag" in
      E) fail "$ctype" ;;
      W) warn "$ctype" ;;
      C)
        if [[ -n "$guard" && ! -d "$REPO_ROOT/$guard" ]]; then
          continue
        fi
        case "$ctype" in
          dir) [[ -d "$REPO_ROOT/$path" ]] || fail "$msg" ;;
          file) [[ -f "$REPO_ROOT/$path" ]] || fail "$msg" ;;
          *) [[ -e "$REPO_ROOT/$path" ]] || fail "$msg" ;;
        esac
        ;;
    esac
  done < <(jq -r --arg us "$US" '
    if .e then ["E", .e]
    elif .w then ["W", .w]
    elif .c then ["C", .c.type, .c.path, .c.guard, .c.msg]
    else empty end
    | join($us)' "$analysis")

  if ((DEEP == 1)); then
    if [[ -z "$CL_KUBE" ]]; then
      fail "${prefix}: cluster.kubernetesMinor is missing or not of the form <major>.<minor>; deep checks skipped"
    else
      deep_variant "$prefix" "$analysis" "$render_json"
    fi
  fi

  stats="$(jq -r '.stats // empty | "\(.projects) AppProjects, \(.appsets) ApplicationSets, \(.apps) Applications (\(.generated) from ApplicationSets)"' "$analysis")"
  log_info "${prefix}: ${stats}; $((errors - before)) error(s)"
  if [[ -n "$DEEP_SUMMARY" ]]; then
    log_info "${prefix} deep: ${DEEP_SUMMARY}"
  fi
}

# ---------------------------------------------------------------------------
# Main
# ---------------------------------------------------------------------------
# Toolchain switches: the current form (dig "<name>" "enabled") and, while
# templates that predate it remain, .Values.toolchains.<name>.enabled.
switches=()
while IFS= read -r name; do
  if [[ -n "$name" ]]; then
    switches+=(--set "toolchains.${name}.enabled=true")
  fi
done < <(
  {
    grep -rhoE 'dig "[a-z0-9-]+" "enabled"' argocd-bootstrap/templates || true
    grep -rhoE '\.Values\.toolchains\.[A-Za-z0-9_]+\.enabled' argocd-bootstrap/templates || true
  } | sed -E -e 's/^dig "([a-z0-9-]+)".*/\1/' -e 's/^\.Values\.toolchains\.([A-Za-z0-9_]+)\.enabled$/\1/' | sort -u
)

for cluster in "${clusters[@]}"; do
  def="clusters/${cluster}/cluster.yaml"
  merged="$WORK/${cluster}.values.json"
  # Values as Helm merges them: maps deep-merged, lists replaced.
  # shellcheck disable=SC2016  # yq variables, not shell expansions
  if ! yq ea -o=json -I=0 '. as $i ireduce ({}; . * $i)' argocd-bootstrap/values.yaml "$def" >"$merged" 2>"$WORK/err"; then
    fail "${cluster}: cannot read ${def}: $(error_summary "$WORK/err")"
    continue
  fi
  CL_REPO="$(jq -r '.git.repoURL // ""' "$merged")"
  CL_KUBE="$(jq -r '(.cluster.kubernetesMinor // "") | tostring | select(test("^[0-9]+\\.[0-9]+$")) | . + ".0"' "$merged")"
  remote="$(jq -r '(.cluster.destination.name // "") | select(. != "in-cluster")' "$merged")"

  # The root Application of a cluster Argo CD runs in comes from bootstrap/.
  # A remote cluster's root is generated by the hub and uses the hub's project.
  echo '[]' >"$WORK/${cluster}.bootstrap.json"
  if [[ -z "$remote" ]]; then
    if helm template bootstrap bootstrap -f "$def" >"$WORK/${cluster}.bootstrap.yaml" 2>"$WORK/err"; then
      yaml_to_json "$WORK/${cluster}.bootstrap.yaml" |
        jq -c 'map(select(.kind == "Application"))' >"$WORK/${cluster}.bootstrap.json"
    else
      fail "${cluster}: helm template bootstrap failed: $(error_summary "$WORK/err")"
    fi
  else
    log_info "${cluster}: remote cluster (destination ${remote}); its root Application belongs to the hub and is not checked here"
  fi

  check_variant "$cluster" configured
  check_variant "$cluster" applicationset --set applicationSet.enabled=true
  if ((${#switches[@]} > 0)); then
    check_variant "$cluster" all-toolchains "${switches[@]}"
  else
    warn "${cluster}: no toolchain switches found in argocd-bootstrap/templates; variant all-toolchains skipped"
  fi
done

if ((DEEP == 1)); then
  while IFS= read -r gk; do
    [[ -n "$gk" ]] || continue
    warn "deep: kind ${gk} has no CRD in the deep pass and no table entry; classified as namespaced"
  done < <(sort -u "$WORK/assumed")
fi

if ((errors > 0)); then
  log_error "${errors} violation(s), ${warnings} warning(s) in ${#clusters[@]} cluster(s)"
  exit 1
fi
log_info "all checks passed for ${#clusters[@]} cluster(s), ${warnings} warning(s)"
